create sequence if not exists purchase_order_number_seq;
create table purchase_orders(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),company_id bigint not null references companies(id),branch_id bigint not null references branches(id),supplier_id bigint not null references suppliers(id),order_number varchar(64) not null,order_date date not null,status varchar(16) not null default 'DRAFT',currency varchar(3) not null default 'IRR',subtotal numeric(18,2) not null default 0,total numeric(18,2) not null default 0,notes varchar(2000),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),version bigint not null default 0,unique(tenant_id,order_number),check(status in ('DRAFT','SUBMITTED','APPROVED','CANCELLED','CLOSED')));
create table purchase_order_lines(id bigint generated by default as identity primary key,tenant_id bigint not null references tenants(id),purchase_order_id bigint not null references purchase_orders(id),product_id bigint not null references products(id),quantity numeric(18,3) not null,unit_price numeric(18,2) not null,line_total numeric(18,2) not null,check(quantity>0 and unit_price>=0 and line_total>=0));
create index purchase_orders_scope_idx on purchase_orders(tenant_id,company_id,branch_id,status);
